// The intake guard (MB_GUARD): one Haiku call over the customer's text BEFORE the main model sees it. It also rates the
// difficulty, so it replaces the separate classifier call when both would run. A refusal costs a fraction of a cent and
// never reaches the main model. It is a filter, not the boundary: the main model has no shell or network, only
// workspace-scoped file tools, and everything it writes is compiled and bytecode-scanned afterwards.
async function guardRequest(rec, ctl) {
  if (R.CFG.guard === "off") return;
  const text = rec.baseBuildId ? `${rec.prompt}\n${rec.changeRequest}` : rec.prompt;
  let verdict = null;
  // Cyrus recipe memory (MB_RECIPES=1, fresh builds): the same call names up to two archetypes from a closed list
  const archIds = RCP.enabled() && !rec.baseBuildId && !rec.imported ? RCP.guardArchetypes() : [];
  let answer = null;
  try { answer = await haikuAsk(rec, ctl, archIds.length ? R.guardPromptWithArchetypes(archIds) : R.GUARD_PROMPT, text, "guard"); verdict = R.parseGuard(answer); } catch { verdict = null; }
  if (verdict && verdict.verdict === "allow" && archIds.length) rec.guardArchetypes = R.parseGuardArchetypes(answer, archIds);
  if (!verdict) {
    event(rec, rec.status, "Intake check unavailable, continuing");
    rec.guard = { verdict: "error" };
    if (R.CFG.guard === "strict") throw fail("unavailable", "We couldn't check this request right now. Please try again in a minute.");
    return;
  }
  rec.guard = verdict;
  if (verdict.verdict === "refuse") {
    throw fail("refused", "We can't build this one. It doesn't read like a Minecraft plugin request, or it goes against our plugin safety rules.", `guard:${verdict.code}`);
  }
  if (verdict.class) rec.guardClass = verdict.class;
}

async function chooseRoute(rec, ctl) {
  if (rec.override) {
    // Customer picked the model (tier). No classifier call; repairs stay on it.
    const h = R.classifyHeuristic(rec.baseBuildId ? `${rec.prompt}\n${rec.changeRequest}` : rec.prompt);
    const m = rec.override.model;
    const up = rec.override.tier ? R.TIERS[R.TIER_UP[rec.override.tier]] : m;
    return { ...h, heuristicClass: h.class, class: rec.override.tier || "override", method: "override", tier: rec.override.tier, models: { generate: m, repairCheap: null, escalate: up, escalateAfter: 2 } };
  }
  const base = rec.baseBuildId ? `${rec.prompt}\n${rec.changeRequest}` : rec.prompt;
  const h = R.classifyHeuristic(rec.prompt);
  let route = { ...h };
  if (rec.baseBuildId) {
    // A change request on an existing plugin: at least as hard as the change itself,
    // and the model must read the old code, so never below the original's class.
    const hc = R.classifyHeuristic(rec.changeRequest);
    route = { ...h, class: R.maxClass(h.class, hc.class), changeScore: hc.score };
  }
  const sameModel = new Set(Object.values(R.CFG.models)).size === 1;
  if (rec.guardClass && R.CFG.classifier === "haiku" && R.CFG.routing && !sameModel) route = { ...route, heuristicClass: route.class, class: rec.guardClass, method: "haiku (intake guard)" };
  else if (R.CFG.classifier === "haiku" && sameModel && R.CFG.routing) route = { ...route, method: "heuristic (all classes use one model, classifier skipped)" };
  else if (R.CFG.classifier === "haiku") {
    const word = await classifyWithHaiku(rec, ctl, base).catch(() => null);
    route = { ...route, heuristicClass: route.class, class: word || route.class, method: word ? "haiku" : "heuristic (haiku failed)" };
  }
  if (!R.CFG.routing) route = { ...route, routedClass: route.class, method: `${route.method}, routing off` };
