}
// The model a failed repair escalates to: one class up from the generation model.
function escalateFrom(model) {
  const m = R.CFG.models;
  if (model === m.simple) return m.standard;
  if (model === m.standard) return m.complex;
  return model;
}

function fail(code, message, detail) { const e = new Error(message); e.code = code; e.detail = detail; return e; }

