"use strict";
// Request routing for the Mod Builder: classify a request as simple / standard /
// complex and pick the generation and repair models for it.
//
// Two classifiers (measured 2026-10-07, see docs "AI Mod Builder: tuning"):
//   haiku (default): one tiny Claude Haiku call that answers with a single word.
//     28 labelled eval prompts: 26/28; 12 held-out prompts: 11/12. ~$0.003 and
//     ~7 s per build. Falls back to the heuristic if the call fails.
//   heuristic: deterministic feature count over the request text. Free and
//     instant, 24/28 on the eval prompts it was tuned on but only 9/12 held out,
//     and its misses route too cheap (standard -> simple).
// Everything is configurable via env (read once at start):
//   MB_ROUTING            on (default) | off  (off = MB_MODEL for every call, the pre-tuning behaviour)
//   MB_CLASSIFIER         haiku (default) | heuristic
//   MB_MODEL_SIMPLE       default claude-sonnet-5-5
//   MB_MODEL_STANDARD     default claude-sonnet-5-5
//   MB_MODEL_COMPLEX      default claude-sonnet-5-5
//   (Eval 2026-10-07: Sonnet 5.5 beat Haiku 4.5 on simple requests -- Haiku took
//   2x the turns, cost more and failed 1/8 -- and beat Sonnet 5 on every class on
//   cost, time and first-try rate. So all classes default to Sonnet 5.5 and the
//   cost lever is Haiku for small first repairs. When all three are the same
//   model the classifier call is skipped; the heuristic class is still recorded.)
//   MB_REPAIR_CHEAP_MODEL default claude-haiku-4-5-20251001 (first repair of a small compile error)
//   MB_REPAIR_CHEAP_FIRST on (default) | off
//   MB_REPAIR_SMALL_MAX   default 3 (compile errors at or below this count are "small")
//   MB_ROUTE_SIMPLE_MAX   default 3   (score below this -> simple)
//   MB_ROUTE_COMPLEX_MIN  default 7.5  (score at or above this -> complex)

const HAIKU = "claude-haiku-4-5-20251001";
const env = (k, d) => (process.env[k] && process.env[k].trim()) || d;
const num = (k, d) => { const n = parseFloat(process.env[k] || ""); return Number.isFinite(n) ? n : d; };

const CFG = {
  routing: env("MB_ROUTING", "on") !== "off",
  classifier: env("MB_CLASSIFIER", "haiku"),
  // Request guard (one Haiku call before the main model): on = refuse on a clear hit, fail OPEN if the guard itself errors;
  // strict = fail CLOSED; off = skip. The sandbox (no Bash/network, workspace-only tools, compile + scan) is the real boundary; the guard saves money and noise.
  guard: env("MB_GUARD", "on"),
  models: {
    simple: env("MB_MODEL_SIMPLE", "claude-sonnet-5-5"),
