"use strict";
// Cyrus build SPEED knobs (2026-10-14, branch feature/cyrus-speed). Pure helpers, no I/O. Measured basis (257 recorded
// builds): generate wall time is 98% explained by OUTPUT tokens (about 9.5 s per 1k tokens, r2 0.98; the turn count adds
// nothing), and 57-78% of those output tokens are thinking, not file content. So the only big lever is fewer thinking
// tokens; everything else (guard 1 s, compile 1.6 s, scan 0.6 s, repairs 10 s mean) is small. Every knob here is OFF by
// default and changes nothing when unset (tested: test/modbuilder-speed.test.ts).
//
//   MB_EFFORT_MAP        "plain=low,designer=medium,texture=medium,sound=medium,creature=high,default=high": the CLI
//                        --effort per lane (lane = creature | design | datapack | texture | sound | plain; `change` for a
//                        change build of any lane; `default` for lanes not listed). One value per BUILD (all calls of a
//                        build use it: changing effort inside a session invalidates the prompt cache). A map entry
//                        wins over MB_EFFORT; MB_EFFORT stays the fallback. Never sent to Haiku.
//   MB_FAST_HINT         "1": appends a short SPEED paragraph to the generate system prompt (decide in a few lines, no
//                        re-verifying facts the sheets already give, write all files together). Prompt version suffix
//                        is recorded in the aiCall so eval runs can be split by it.
//   MB_MAX_THINKING_TOKENS  integer cap passed as MAX_THINKING_TOKENS to the generate/repair child (not Haiku). UNVERIFIED
//                        on Sonnet 5.x adaptive thinking: only keep it if the eval shows the output tokens drop.
const EFFORTS = ["low", "medium", "high", "xhigh", "max"];
const LANES = ["creature", "design", "datapack", "texture", "sound", "plain", "change", "default"];

/** "plain=low, texture=medium" -> { plain: "low", texture: "medium" } (unknown lanes / efforts are dropped). */
function parseEffortMap(raw) {
  const out = {};
  for (const part of String(raw || "").split(/[,\s]+/)) {
    const m = /^([a-z]+)\s*[=:]\s*([a-z]+)$/i.exec(part.trim());
    if (!m) continue;
    const lane = m[1].toLowerCase(), eff = m[2].toLowerCase();
    if (LANES.includes(lane) && EFFORTS.includes(eff)) out[lane] = eff;
  }
  return out;
}

/** The lane a build belongs to, by the heaviest asset it plans (creature > design > datapack > texture > sound > plain). */
function laneOf(rec) {
  const a = (rec && rec.assets) || {};
  if (a.creature) return "creature";
  if (a.design) return "design";
  if (a.datapack) return "datapack";
  if (a.texture) return "texture";
  if (a.sound) return "sound";
  return "plain";
}

/** Effort for one call: map (lane, then change, then default) > fallback > null. Haiku never gets an effort. */
function effortFor(model, rec, map, fallback) {
  if (/haiku/i.test(String(model))) return null;
  if (map && Object.keys(map).length) {
    const lane = laneOf(rec);
    const e = (rec && rec.baseBuildId && map.change) || map[lane] || map.default;
    if (e) return e;
  }
  return fallback || null;
}

const FAST_HINT = [
  "SPEED: keep your reasoning short. Decide the design in a few lines, do not list alternatives, and do not re-derive API",
  "names or signatures the sheets already give. Then write every file of the plugin in as few responses as you can (several",
  "Write calls in one response). Do not re-read files you just wrote.",
].join(" ");

const fastHintOn = (env = process.env) => env.MB_FAST_HINT === "1";
function thinkingCap(env = process.env) {
  const n = parseInt(env.MB_MAX_THINKING_TOKENS || "", 10);
  return Number.isFinite(n) && n >= 1024 && n <= 128000 ? n : null;
}

module.exports = { EFFORTS, LANES, parseEffortMap, laneOf, effortFor, FAST_HINT, fastHintOn, thinkingCap };
